mapper.update:
UPDATE post
id = #{dto.id}, post_tag_id = #{dto.postTagId}, content_delta = #{dto.contentDelta}, title = #{dto.title}, plain_text = #{dto.plainText}, word_count = #{dto.wordCount}, cover = #{dto.cover}, visibility = #{dto.visibility},
WHERE id = #{dto.id} and user_id=#{userId}

mapper.select:
select id, user_id, post_tag_id, content_delta, title, plain_text, word_count, cover, like_count, comment_count, create_time, update_time
from post
where state = 0 and (visibility = 0  or user_id = #{userId})

    and post_tag_id = #{dto.postTagId}


    and id < #{dto.lastPostId}

order by id desc
limit #{dto.size}

